/** Shapes of the bundled endpoint catalog (catalog/endpoints.json), generated by scripts/sync-docs.ts. */

export interface Field {
  name: string;
  type: string;
  required: boolean;
  description: string;
  /** Allowed values, taken from the swagger spec where the docs page doesn't list them. */
  enum?: string[];
  fields?: Field[];
}

export type ParamIn = "path" | "query" | "body";

export interface Param extends Field {
  in: ParamIn;
}

export interface Endpoint {
  /** Stable id taken from the docs anchor, e.g. "list-invoices-v3". */
  id: string;
  /** Docs section, e.g. "Invoices". */
  group: string;
  method: "GET" | "POST" | "PUT" | "DELETE" | "PATCH";
  path: string;
  summary: string;
  description: string;
  deprecated: boolean;
  params: Param[];
  response: Field[];
}

export interface Catalog {
  source: string;
  syncedAt: string;
  endpoints: Endpoint[];
}
